import 'package:flutter/material.dart';
import 'package:fl_chart/fl_chart.dart';
void main()=>runApp(const TravelApp());
class TravelApp extends StatelessWidget{const TravelApp({super.key});@override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,title:'Roamly',theme:ThemeData(colorScheme:ColorScheme.fromSeed(seedColor:Colors.cyan),useMaterial3:true),home:const TravelHome());}
class TravelHome extends StatelessWidget{const TravelHome({super.key});@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Roamly • Trip Insights')),body:ListView(padding:const EdgeInsets.all(16),children:[const Icon(Icons.explore,size:54,color:Colors.teal),const Text('Explore your next escape',textAlign:TextAlign.center,style:TextStyle(fontSize:23,fontWeight:FontWeight.bold)),const SizedBox(height:14),ClipRRect(borderRadius:BorderRadius.circular(16),child:Image.asset('assets/images/coast.png',height:170,fit:BoxFit.cover)),const SizedBox(height:18),const Text('Featured destination',style:TextStyle(fontWeight:FontWeight.bold,fontSize:20)),ClipRRect(borderRadius:BorderRadius.circular(14),child:Image.network('https://picsum.photos/seed/travel-lab/800/300',height:150,fit:BoxFit.cover,errorBuilder:(_,__,___)=>Container(height:120,color:Colors.teal.shade100,child:const Icon(Icons.landscape,size:50)))),const SizedBox(height:12),const Row(mainAxisAlignment:MainAxisAlignment.spaceAround,children:[_Feature(Icons.flight,'Flights'),_Feature(Icons.hotel,'Stays'),_Feature(Icons.hiking,'Activities'),_Feature(Icons.map,'Maps')]),const SizedBox(height:20),const Text('Monthly travel budget (₹)',style:TextStyle(fontWeight:FontWeight.bold,fontSize:20)),SizedBox(height:230,child:BarChart(BarChartData(maxY:5000,barGroups:[for(int i=0;i<4;i++)BarChartGroupData(x:i,barRods:[BarChartRodData(toY:[3200,4100,2800,4600][i],width:28,borderRadius:BorderRadius.circular(5))])],titlesData:FlTitlesData(bottomTitles:AxisTitles(sideTitles:SideTitles(showTitles:true,getTitlesWidget:(v,m)=>Padding(padding:const EdgeInsets.only(top:8),child:Text(['Jan','Feb','Mar','Apr'][v.toInt().clamp(0,3)])))),rightTitles:const AxisTitles(sideTitles:SideTitles(showTitles:false))))))]));}}
class _Feature extends StatelessWidget{final IconData icon;final String label;const _Feature(this.icon,this.label);@override Widget build(BuildContext c)=>Column(children:[Icon(icon,size:30),Text(label)]);}
